// Format Slack Block-Kit Message
const res = $input.first().json;

let messageText = '';
let blocks = [];

if (res.is_duplicate) {
  messageText = `⚠️ Duplicate Detected: ${res.name} is a duplicate of ${res.duplicate_of} (${Math.round((res.confidence || 0) * 100)}% match)`;
  blocks = [
    {
      type: 'header',
      text: { type: 'plain_text', text: '⚠️ Duplicate Applicant Flagged', emoji: true }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*Name:* ${res.name}\n*Duplicate Of:* \`${res.duplicate_of}\`\n*Confidence:* ${Math.round((res.confidence || 0) * 100)}%\n*Reasoning:* ${res.reasoning || 'N/A'}`
      }
    }
  ];
} else {
  const fitScore = res.fit_score !== null ? `${res.fit_score}/100` : 'N/A';
  const tags = (res.sector_tags || []).map(t => `#${t}`).join(' ');
  const intros = (res.top_introductions || []).map(i => `• *${i.matched_person_name}* (${i.matched_person_company || 'Stealth'}) - ${i.shared_context} [${i.match_band.toUpperCase()}]`).join('\n') || 'None suggested';

  messageText = `✨ New Member Ingested: ${res.name} (${res.role_title} @ ${res.company || 'Stealth'}) | Fit Score: ${fitScore}`;
  blocks = [
    {
      type: 'header',
      text: { type: 'plain_text', text: '✨ New Offline Member Processed', emoji: true }
    },
    {
      type: 'section',
      fields: [
        { type: 'mrkdwn', text: `*Name:*\n${res.name}` },
        { type: 'mrkdwn', text: `*Role & Company:*\n${res.role_title || 'N/A'} at ${res.company || 'Stealth'}` },
        { type: 'mrkdwn', text: `*Role Type / Seniority:*\n${res.role_type || 'N/A'} (${res.seniority || 'N/A'})` },
        { type: 'mrkdwn', text: `*Fit Score:*\n🎯 *${fitScore}*` }
      ]
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*Sectors:* ${tags || 'General'}\n*Fit Reasoning:* _${res.fit_score_reasoning || 'N/A'}_`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*Top Intro Recommendations:*\n${intros}`
      }
    }
  ];
}

return {
  json: {
    slack_payload: {
      text: messageText,
      blocks: blocks
    },
    pipeline_result: res
  }
};
